"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { ArrowUpRight } from "react-feather";
import { Button, Flex, styled, Text, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useEarnContext } from "../ContextProvider";
import { mockVaultData } from "../MockVaultData";
const CardWrapper = styled(Flex, {
  flexDirection: "column",
  width: "100%",
  gap: "$spacing16"
});
const Card = styled(Flex, {
  flexDirection: "column",
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  p: "$spacing24",
  gap: "$spacing24"
});
const LabelText = styled(Text, {
  color: "$neutral2",
  variant: "body3"
});
const ValueText = styled(Text, {
  color: "$neutral1",
  variant: "body3"
});
const Divider = styled(Flex, {
  height: 1,
  width: "100%",
  backgroundColor: "$surface3"
});
const ActionButton = styled(Button, {
  borderRadius: "$roundedFull",
  py: "$spacing12"
});
const DataRow = ({
  label,
  value,
  subValue,
  icon
}) => <Flex row justifyContent="space-between" alignItems="center" width="100%">
    <LabelText color="$neutral2" variant="body2">
      {label}
    </LabelText>
    <Flex row alignItems="flex-end" gap={"$spacing8"}>
      <Flex flexDirection="row" alignItems="center" gap="$gap8">
        {icon}
        <ValueText color="$neutral1" variant="body2">
          {value}
        </ValueText>
      </Flex>
      {subValue && <Flex
  $sm={{ display: "none" }}
  backgroundColor="$surface3"
  paddingHorizontal="$spacing8"
  paddingVertical="$spacing2"
  borderRadius="$roundedFull"
>
          <Text variant="body4" color="$neutral2">
            {subValue}
          </Text>
        </Flex>}
    </Flex>
  </Flex>;
export default function EarnCard() {
  const { formatFiatPrice } = useFormatter();
  const colors = useSporeColors();
  const { openTransaction, activeTab } = useEarnContext();
  return <CardWrapper>
      {mockVaultData.map((vault) => <Card key={vault.id}>
          {
    /* Header */
  }
          <Flex row justifyContent="space-between" alignItems="center" width="100%">
            <Flex row alignItems="center" gap="$gap12">
              <PortfolioLogo
    chainId={1}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={32}
  />
              <Flex row alignItems="center" gap="$gap8">
                <LabelText>{vault.name}</LabelText>
                <ArrowUpRight size={18} color={colors.neutral2.val} />
              </Flex>
            </Flex>
            <Flex alignItems="center" gap="$gap4">
              <ValueText color={"$neutral1"}>{vault.apy.toFixed(2)}%</ValueText>
            </Flex>
          </Flex>

          <Divider />

          {
    /* Stats */
  }
          <Flex flexDirection="column" gap="$gap16">
            <DataRow
    label="Total Deposits"
    value={formatFiatPrice({ price: vault.deposits, type: NumberType.FiatTokenStats })}
    subValue={"$" + (vault.deposits / 1e6).toFixed(2) + "M"}
  />
            <DataRow
    label="Liquidity"
    value={formatFiatPrice({ price: vault.liquidity, type: NumberType.FiatTokenStats })}
    subValue={"$" + (vault.liquidity / 1e6).toFixed(2) + "M"}
  />
            <DataRow
    label="Curator"
    value={vault.curator?.name || "Unknown"}
    icon={vault.curator?.name ? <Flex
      width={16}
      height={16}
      borderRadius="$roundedFull"
      backgroundColor={vault.curator.name.includes("Stakehouse") ? "$green" : "$red"}
      justifyContent="center"
      alignItems="center"
    >
                    {
      /* Simplified icon placeholder */
    }
                  </Flex> : null}
  />
            <DataRow
    label="Exposure"
    value={<Flex flexDirection="row" gap="-4px">
                  {
      /* Mock Exposure Icons */
    }
                  <Flex
      width={20}
      height={20}
      borderRadius="$roundedFull"
      backgroundColor="$surface3"
      borderWidth={1}
      borderColor="$surface1"
      justifyContent="center"
      alignItems="center"
    >
                    <img
      src="https://raw.githubusercontent.com/uniswap/assets/master/blockchains/ethereum/assets/0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599/logo.png"
      width="100%"
      height="100%"
      style={{ borderRadius: "50%" }}
    />
                  </Flex>
                  <Flex
      width={20}
      height={20}
      borderRadius="$roundedFull"
      backgroundColor="$surface3"
      borderWidth={1}
      borderColor="$surface1"
      marginLeft="-8px"
      justifyContent="center"
      alignItems="center"
    >
                    <img
      src="https://raw.githubusercontent.com/uniswap/assets/master/blockchains/ethereum/assets/0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2/logo.png"
      width="100%"
      height="100%"
      style={{ borderRadius: "50%" }}
    />
                  </Flex>
                </Flex>}
  />
          </Flex>

          <Divider />

          <Flex flexDirection="row" gap="$spacing18" justifyContent="space-between">
            <ActionButton onPress={() => openTransaction(vault, "deposit")}>Deposit</ActionButton>
            {activeTab === "positions" && <ActionButton onPress={() => openTransaction(vault, "withdraw")}>Withdraw</ActionButton>}
          </Flex>
        </Card>)}
    </CardWrapper>;
}
